(() => {
const $ = s => document.querySelector(s);
const store = {
  read(key, fallback=[]) { try { const v=JSON.parse(localStorage.getItem('vsc_'+key)); return v ?? fallback; } catch { return fallback; } },
  write(key, value) { localStorage.setItem('vsc_'+key, JSON.stringify(value)); },
  id(prefix) { return prefix+'-'+Date.now().toString().slice(-6)+'-'+Math.floor(Math.random()*90+10); }
};
const demo = [
 {id:'u1',name:'Demo Customer',email:'user@gmail.com',password:'12345',role:'customer',phone:'9876543210'},
 {id:'a1',name:'Admin User',email:'admin@gmail.com',password:'12345',role:'admin',phone:'9000000001'},
 {id:'t1',name:'Arun Kumar',email:'technision@gmail.com',password:'12345',role:'technician',phone:'9000000002',specialization:'Engine Diagnostics & General Service',experience:6,branch:'Chennai Central',status:'Available',availability:'Available'},
 {id:'t2',name:'Priya Raman',email:'priya.tech@vsc.demo',password:'12345',role:'technician',phone:'9000000003',specialization:'Electrical Systems & AC Repair',experience:4,branch:'Chennai Central',status:'Available',availability:'Available'},
 {id:'t3',name:'Karthik Raj',email:'karthik.tech@vsc.demo',password:'12345',role:'technician',phone:'9000000004',specialization:'Brakes, Suspension & Tyres',experience:8,branch:'Chennai South',status:'Busy',availability:'Busy'}
];
function initData(){
 if(!localStorage.getItem('vsc_users')) store.write('users',demo);
 if(!localStorage.getItem('vsc_technicians')) store.write('technicians',demo.filter(u=>u.role==='technician'));
 if(!localStorage.getItem('vsc_vehicles')) store.write('vehicles',[
  {id:'VSC-V101',ownerId:'u1',owner:'Demo Customer',make:'Hyundai',model:'Creta',year:2022,registration:'TN 09 AB 1234',fuel:'Petrol',km:28500,color:'White'},
  {id:'VSC-V102',ownerId:'u1',owner:'Demo Customer',make:'Maruti Suzuki',model:'Swift',year:2020,registration:'TN 10 CD 5678',fuel:'Petrol',km:41200,color:'Silver'}
 ]);
 if(!localStorage.getItem('vsc_appointments')) store.write('appointments',[
  {id:'APT-1001',customerId:'u1',customer:'Demo Customer',email:'user@gmail.com',phone:'9876543210',vehicleId:'VSC-V101',vehicle:'Hyundai Creta',registration:'TN 09 AB 1234',package:'Full Service',date:futureDate(2),slot:'10:00 AM - 11:00 AM',problem:'Routine full service and engine oil change',km:28500,priority:'Normal',status:'Pending Approval',createdAt:new Date().toISOString()}
 ]);
 if(!localStorage.getItem('vsc_jobs')) store.write('jobs',[
  {id:'JC-1001',appointmentId:'APT-DEMO',customerId:'u1',customer:'Demo Customer',email:'user@gmail.com',vehicle:'Maruti Swift',registration:'TN 10 CD 5678',package:'Oil Change',complaint:'Engine oil change and general inspection',diagnosis:'Oil and filter replaced; inspection completed',technicianId:'t1',technician:'Arun Kumar',startDate:todayDate(),deliveryDate:futureDate(1),estimatedCost:2800,actualCost:2800,status:'In Progress',tasks:['Oil and filter replacement','General inspection'],updatedAt:new Date().toISOString()}
 ]);
 if(!localStorage.getItem('vsc_payments')) store.write('payments',[]);
 if(!localStorage.getItem('vsc_feedback')) store.write('feedback',[]);
}
function futureDate(days){const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function todayDate(){return new Date().toISOString().slice(0,10)}
initData();
const getUsers=()=>store.read('users',demo), getVehicles=()=>store.read('vehicles'), getAppointments=()=>store.read('appointments'), getJobs=()=>store.read('jobs'), getTechs=()=>store.read('technicians');
let mode='login', currentUser=null, activePage='dashboard', searchText='';
const navByRole={
 customer:[['dashboard','Dashboard','▦'],['vehicles','My Vehicles','▱'],['appointments','Appointments','▣'],['jobcards','Job Cards & Service History','▤'],['invoices','Invoices & Payments','₹'],['feedback','Feedback','☆'],['profile','My Profile','♙']],
 admin:[['dashboard','Dashboard','▦'],['appointments','Appointments & Approvals','▣'],['customers','Customers','♙'],['vehicles','Vehicles','▱'],['technicians','Technicians','⚒'],['jobcards','Job Cards','▤'],['invoices','Billing & Payments','₹'],['reports','Reports','▥']],
 technician:[['dashboard','Dashboard','▦'],['myjobs','My Assigned Jobs','▤'],['jobcards','Service Updates','⚒'],['parts','Parts Requests','▣'],['profile','My Profile','♙']]
};
const titles={dashboard:'Dashboard',vehicles:'My Vehicles',appointments:'Appointments',jobcards:'Job Cards',invoices:'Invoices & Payments',feedback:'Customer Feedback',profile:'My Profile',customers:'Customer Management',technicians:'Technician Management',reports:'Reports & Analytics',myjobs:'My Assigned Jobs',parts:'Parts Requests'};
function showMessage(text,success=false){const m=$('#authMessage');m.textContent=text;m.classList.remove('hidden','success');if(success)m.classList.add('success')}
function setMode(next){mode=next;$('#loginTab').classList.toggle('active',next==='login');$('#signupTab').classList.toggle('active',next==='signup');$('#nameField').classList.toggle('hidden',next==='login');$('#roleField').classList.toggle('hidden',next==='login');$('#authTitle').textContent=next==='login'?'Welcome back!':'Create your account';$('#authSubtitle').textContent=next==='login'?'Sign in to continue to your workspace.':'Join VSC and manage your vehicle services.';$('#authSubmit').innerHTML=next==='login'?'Login <span>→</span>':'Create account <span>→</span>';showMessage('');}
$('#loginTab').addEventListener('click',()=>setMode('login'));$('#signupTab').addEventListener('click',()=>setMode('signup'));
$('#togglePassword').addEventListener('click',()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';});
document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.demo;const email=kind==='user'?'user@gmail.com':kind==='admin'?'admin@gmail.com':'technision@gmail.com';$('#email').value=email;$('#password').value='12345';setMode('login');}));
$('#authForm').addEventListener('submit',e=>{
 e.preventDefault();const email=$('#email').value.trim().toLowerCase(),password=$('#password').value;
 if(mode==='signup'){
  const name=$('#fullName').value.trim(),role=$('#role').value;
  if(!name){showMessage('Please enter your full name.');return}
  if(password.length<5){showMessage('Use at least 5 characters for this demo password.');return}
  const users=getUsers();if(users.some(u=>u.email.toLowerCase()===email)){showMessage('This email is already registered. Please log in.');return}
  const user={id:store.id('USR'),name,email,password,role,phone:'',...(role==='technician'?{specialization:'General Service',experience:0,branch:'Main Branch',status:'Available',availability:'Available'}:{})};
  users.push(user);store.write('users',users);if(role==='technician'){const ts=getTechs();ts.push(user);store.write('technicians',ts)}showMessage('Account created successfully. Please log in.',true);$('#email').value=email;$('#password').value='';setMode('login');return;
 }
 const user=getUsers().find(u=>u.email.toLowerCase()===email&&u.password===password);
 if(!user){showMessage('Email or password is incorrect. Try one of the demo accounts below.');return}
 currentUser=user;sessionStorage.setItem('vsc_session',JSON.stringify({id:user.id,name:user.name,email:user.email,role:user.role}));openApp();
});
function openApp(){const session=JSON.parse(sessionStorage.getItem('vsc_session')||'null');if(!session)return;currentUser=getUsers().find(u=>u.id===session.id)||session;$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#profileName').textContent=currentUser.name;$('#profileRole').textContent=roleLabel(currentUser.role);$('#profileAvatar').textContent=initials(currentUser.name);$('#roleCaption').textContent=roleLabel(currentUser.role).toUpperCase()+' WORKSPACE';renderNav();go('dashboard');}
function roleLabel(role){return role==='admin'?'Administrator':role==='technician'?'Technician':'Customer'}
function initials(name){return String(name||'U').split(/\s+/).map(p=>p[0]).join('').slice(0,2).toUpperCase()}
function renderNav(){const nav=navByRole[currentUser.role]||navByRole.customer;$('#sideNav').innerHTML=nav.map(([id,label,icon])=>`<button class="nav-link ${id===activePage?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('');}
$('#sideNav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
$('#logoutBtn').addEventListener('click',()=>{sessionStorage.removeItem('vsc_session');currentUser=null;$('#appView').classList.add('hidden');$('#loginView').classList.remove('hidden');$('#password').value='';setMode('login');toast('You have logged out.','success')});
$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#globalSearch').addEventListener('input',e=>{searchText=e.target.value.trim().toLowerCase();renderPage()});
$('#notificationBtn').addEventListener('click',()=>toast(notificationText()));
function notificationText(){if(currentUser.role==='admin'){const n=getAppointments().filter(a=>a.status==='Pending Approval').length;return n?`${n} appointment(s) waiting for your approval.`:'No pending appointment approvals.'}if(currentUser.role==='technician'){const n=getJobs().filter(j=>j.technicianId===currentUser.id&&j.status!=='Delivered').length;return `You have ${n} active assigned job(s).`}return 'Your VSC notifications are up to date.'}
function go(page){activePage=page;$('#sidebar').classList.remove('open');renderNav();renderPage();}
function setHeading(title,subtitle,actions=''){ $('#pageEyebrow').textContent=roleLabel(currentUser.role).toUpperCase()+' WORKSPACE';$('#pageTitle').textContent=title;$('#pageSubtitle').textContent=subtitle;$('#headingActions').innerHTML=actions;}
function actionButton(label,action,kind='primary'){return `<button class="btn ${kind}" data-action="${action}">${label}</button>`}
function renderPage(){if(!currentUser)return;const role=currentUser.role;const page=activePage;
 if(page==='dashboard')return role==='admin'?adminDashboard():role==='technician'?techDashboard():customerDashboard();
 if(page==='appointments')return role==='admin'?adminAppointments():customerAppointments();
 if(page==='vehicles')return role==='admin'?adminVehicles():customerVehicles();
 if(page==='customers')return adminCustomers();
 if(page==='technicians')return adminTechnicians();
 if(page==='jobcards'||page==='myjobs')return role==='technician'?techJobs():role==='admin'?adminJobs():customerJobs();
 if(page==='invoices')return invoicesPage();
 if(page==='feedback')return feedbackPage();
 if(page==='profile')return profilePage();
 if(page==='parts')return partsPage();
 if(page==='reports')return reportsPage();
}
function stat(label,value,note,icon,color='purple'){const colors={purple:['#f0eaff','#7852d3'],blue:['#eaf2ff','#4389e8'],green:['#e7f8ef','#1eaa71'],orange:['#fff3e3','#e89532'],red:['#ffedef','#d64e5b']};let c=colors[color]||colors.purple;return `<article class="stat-card"><div class="stat-head"><span>${label}</span><span class="stat-icon" style="background:${c[0]};color:${c[1]}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`}
function panelHead(title,subtitle='',link=''){return `<div class="panel-head"><div><h3>${title}</h3>${subtitle?`<p>${subtitle}</p>`:''}</div>${link}</div>`}
function matches(obj){return !searchText||JSON.stringify(obj).toLowerCase().includes(searchText)}
function statusPill(s){const v=String(s||'Pending').toLowerCase();let c=v.includes('complete')||v.includes('paid')||v.includes('available')||v==='approved'||v==='delivered'? 'green':v.includes('progress')||v.includes('busy')||v.includes('confirmed')?'blue':v.includes('pending')||v.includes('waiting')||v.includes('requested')?'orange':v.includes('reject')||v.includes('overdue')?'red':'gray';return `<span class="pill ${c}">${esc(s||'Pending')}</span>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){return '₹'+Number(n||0).toLocaleString('en-IN')}
function dateLabel(d){if(!d)return '—';try{return new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}catch{return d}}
function adminDashboard(){
 const apps=getAppointments(),jobs=getJobs(),vehicles=getVehicles(),users=getUsers(),techs=getTechs(),pending=apps.filter(a=>a.status==='Pending Approval'),active=jobs.filter(j=>!['Delivered','Completed'].includes(j.status));
 const revenue=store.read('payments').reduce((s,p)=>s+Number(p.amount||0),0);
 setHeading('Good '+greeting()+', '+currentUser.name+' 👋','Here’s what’s happening at your service center today.',actionButton('＋ Create Job Card','new-job'));
 const jobStages=['Received','In Progress','Waiting Parts','Ready for Delivery'];const cols=jobStages.map((stage,i)=>{const list=jobs.filter(j=>stage==='Ready for Delivery'?['Completed','Ready for Delivery'].includes(j.status):j.status===stage).filter(matches);return `<div class="job-column"><div class="column-head"><span class="dot" style="background:${['#8055d5','#e89b32','#a17be7','#21b579'][i]}"></span>${stage}<span class="count">${list.length}</span></div>${list.slice(0,3).map(jobCardMini).join('')||'<div class="empty-state">No jobs</div>'}</div>`}).join('');
 const activity=[...apps.slice(-3).reverse().map(a=>({icon:'▣',title:'Appointment '+a.status.toLowerCase(),detail:`${a.customer} · ${dateLabel(a.date)}`})),...jobs.slice(-2).map(j=>({icon:'⚒',title:'Job card '+j.id,detail:`${j.vehicle} · ${j.status}`}))].slice(0,4);
 $('#pageContent').innerHTML=`<div class="stat-grid">${stat('Total Customers',users.filter(u=>u.role==='customer').length,'Registered customer accounts','♙','purple')}${stat('Vehicles Registered',vehicles.length,'Linked to customers','▱','blue')}${stat('Appointments Today',apps.filter(a=>a.date===todayDate()).length,`${pending.length} awaiting approval`,'▣','orange')}${stat('Vehicles Under Service',active.length,'Active job cards','⚒','green')}</div>
 <div class="content-grid"><div><section class="panel">${panelHead('Live Job Cards','Monitor service work by current status',`<button class="text-link" data-action="go-jobs">View all →</button>`)}<div class="job-columns">${cols}</div></section>
 <section class="panel">${panelHead('Appointment approvals',`${pending.length} appointment(s) need review`,actionButton('Review appointments','go-appointments','secondary'))}${pending.length?table(['Customer / vehicle','Requested date','Service','Status','Action'],pending.slice(0,4).map(a=>[`<strong>${esc(a.customer)}</strong><small>${esc(a.vehicle)} · ${esc(a.registration)}</small>`,dateLabel(a.date),esc(a.package),statusPill(a.status),`<button class="btn small primary" data-action="review-appointment" data-id="${a.id}">Review</button>`])):'<div class="empty-state">No appointments waiting for approval.</div>'}</section></div>
 <div><section class="panel">${panelHead('Quick insights')}<div class="insights">${insight('Technicians',techs.length,'Across demo branches')}${insight('Pending approvals',pending.length,pending.length?'Needs admin review':'All caught up')}${insight('Estimated active work',money(active.reduce((s,j)=>s+Number(j.estimatedCost||0),0)),'Across open job cards')}</div></section>
 <section class="panel">${panelHead('Recent activity')}<div class="activity-list">${activity.map(a=>`<div class="activity-item"><span class="activity-icon">${a.icon}</span><div><b>${esc(a.title)}</b><small>${esc(a.detail)}</small></div></div>`).join('')||'<div class="empty-state">Activity will appear here.</div>'}</div></section></div></div>`;
}
function greeting(){const h=new Date().getHours();return h<12?'Morning':h<17?'Afternoon':'Evening'}
function insight(label,value,note){return `<div class="insight-card"><div class="insight-label">${label}</div><div class="insight-value">${value}</div><div class="insight-note">${note}</div></div>`}
function jobCardMini(j){return `<article class="job-card"><h4>${esc(j.vehicle)}</h4><div class="plate">${esc(j.registration||'Registration pending')}</div><div class="job-service">${esc(j.package||j.complaint||'Service')}</div><div class="job-bottom"><span>${esc(j.technician||'Unassigned')}</span>${statusPill(j.status)}</div></article>`}
function customerDashboard(){
 const vehicles=getVehicles().filter(v=>v.ownerId===currentUser.id||v.owner===currentUser.name),apps=getAppointments().filter(a=>a.customerId===currentUser.id),jobs=getJobs().filter(j=>j.customerId===currentUser.id),upcoming=apps.filter(a=>!['Cancelled','Rejected'].includes(a.status)).sort((a,b)=>a.date.localeCompare(b.date)),invoices=store.read('payments').filter(p=>p.customerId===currentUser.id),due=invoices.filter(p=>p.status!=='Paid').reduce((s,p)=>s+Number(p.amount||0),0);
 setHeading('Welcome back, '+currentUser.name+' 👋','Keep your vehicle in top condition.',actionButton('＋ Book a service','new-appointment'));
 $('#pageContent').innerHTML=`<div class="stat-grid">${stat('Registered Vehicles',vehicles.length,'Your vehicles','▱','blue')}${stat('Upcoming Appointments',upcoming.length,'Booked service visits','▣','purple')}${stat('Services Completed',jobs.filter(j=>['Completed','Delivered'].includes(j.status)).length,'Job card history','✓','green')}${stat('Pending Bills',money(due),'Outstanding demo invoices','₹','orange')}</div>
 <div class="content-grid"><div><section class="panel">${panelHead('My Vehicles','Your registered vehicles',`<button class="text-link" data-action="go-vehicles">View all →</button>`)}${vehicles.length?`<div class="two-col">${vehicles.slice(0,4).map(vehicleCard).join('')}</div>`:'<div class="empty-state">No vehicles linked to your account yet.</div>'}</section>
 <section class="panel">${panelHead('Upcoming Appointments','Track approval and service schedule',`<button class="text-link" data-action="go-appointments">View all →</button>`)}${upcoming.length?table(['Appointment','Vehicle','Date & time','Status'],upcoming.slice(0,5).map(a=>[`<strong>${a.id}</strong><small>${esc(a.package)}</small>`,`${esc(a.vehicle)}<small>${esc(a.registration)}</small>`,`${dateLabel(a.date)}<small>${esc(a.slot)}</small>`,statusPill(a.status)])):'<div class="empty-state">No appointments yet. Book your first service.</div>'}</section></div>
 <div><section class="panel">${panelHead('Service journey')}<div class="timeline">${[['Appointment booked','Request is submitted for admin review'],['Admin approval','A technician is assigned'],['Job card shared','View diagnosis, cost and delivery date'],['Vehicle delivered','Review final service and invoice']].map((x,i)=>`<div class="timeline-item"><span class="timeline-dot"></span><div><b>${x[0]}</b><small>${x[1]}</small></div></div>`).join('')}</div></section>
 <section class="panel">${panelHead('Latest job card')}${jobs.length?jobSummary(jobs[0]):'<div class="empty-state">Your approved job cards will appear here.</div>'}</section></div></div>`;
}
function techDashboard(){
 const jobs=getJobs().filter(j=>j.technicianId===currentUser.id||j.technician===currentUser.name),active=jobs.filter(j=>!['Completed','Delivered'].includes(j.status));
 setHeading('Good '+greeting()+', '+currentUser.name+' 👋','Review your assigned work and keep service progress updated.',actionButton('View assigned jobs','go-myjobs'));
 $('#pageContent').innerHTML=`<div class="stat-grid">${stat('Assigned Jobs',jobs.length,'All assigned job cards','▤','purple')}${stat('In Progress',jobs.filter(j=>j.status==='In Progress').length,'Currently being serviced','⚒','blue')}${stat('Waiting for Parts',jobs.filter(j=>j.status==='Waiting Parts').length,'Parts / approval needed','▣','orange')}${stat('Completed',jobs.filter(j=>['Completed','Delivered'].includes(j.status)).length,'Completed job cards','✓','green')}</div>
 <div class="content-grid"><div><section class="panel">${panelHead('My assigned jobs','Update the status as work progresses')}${jobs.length?table(['Job card / vehicle','Customer issue','Delivery date','Status','Action'],jobs.filter(matches).map(j=>[`<strong>${j.id}</strong><small>${esc(j.vehicle)} · ${esc(j.registration)}</small>`,esc(j.complaint||j.package),dateLabel(j.deliveryDate),statusPill(j.status),`<button class="btn small primary" data-action="update-job" data-id="${j.id}">Update</button>`])):'<div class="empty-state">No jobs assigned to you yet. Approved appointments create job cards.</div>'}</section></div>
 <div><section class="panel">${panelHead('Quick actions')}<div class="insights"><button class="btn secondary full" data-action="go-myjobs">▤ &nbsp; View assigned jobs</button><button class="btn outline full" data-action="go-parts">＋ &nbsp; Request spare parts</button><button class="btn outline full" data-action="go-profile">♙ &nbsp; View my profile</button></div></section><section class="panel">${panelHead('Your expertise')}<div class="insight-value" style="font-size:15px">${esc(currentUser.specialization||'General Service')}</div><p class="muted">${Number(currentUser.experience||0)} years experience · ${esc(currentUser.branch||'Main Branch')}</p><div class="metric-row"><span>Current availability</span>${statusPill(currentUser.status||'Available')}</div></section></div></div>`;
}
function table(headers,rows){if(!rows.length)return '<div class="empty-state">No matching records found.</div>';return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function vehicleCard(v){return `<article class="vehicle-card"><div class="vehicle-top"><span class="vehicle-icon">🚘</span><div><h3>${esc(v.make)} ${esc(v.model)}</h3><p>${esc(v.registration)}</p></div></div><div class="card-detail-grid"><div><div class="detail-label">Year / fuel</div><div class="detail-value">${esc(v.year)} · ${esc(v.fuel)}</div></div><div><div class="detail-label">Odometer</div><div class="detail-value">${Number(v.km||0).toLocaleString('en-IN')} km</div></div></div></article>`}
function jobSummary(j){return `<div class="vehicle-top"><span class="vehicle-icon">▤</span><div><h3>${esc(j.id)} · ${esc(j.vehicle)}</h3><p>${esc(j.package)}</p></div></div><div class="metric-row"><span>Technician</span><b>${esc(j.technician||'Not assigned')}</b></div><div class="metric-row"><span>Expected delivery</span><b>${dateLabel(j.deliveryDate)}</b></div><div class="metric-row"><span>Status</span>${statusPill(j.status)}</div><button class="btn secondary full" data-action="view-job" data-id="${j.id}">View job card details</button>`}
function adminAppointments(){const list=getAppointments().filter(matches).sort((a,b)=>b.createdAt?.localeCompare(a.createdAt||'')||0);setHeading('Appointments & Approvals','Review customer requests, check technician expertise and approve a service slot.',actionButton('＋ Create appointment','new-appointment'));$('#pageContent').innerHTML=`<div class="stat-grid">${stat('All Appointments',list.length,'All requests','▣','purple')}${stat('Pending Approval',list.filter(a=>a.status==='Pending Approval').length,'Requires review','◷','orange')}${stat('Confirmed',list.filter(a=>a.status==='Confirmed').length,'Technician assigned','✓','green')}${stat('Rejected / Cancelled',list.filter(a=>['Rejected','Cancelled'].includes(a.status)).length,'Closed requests','×','red')}</div><section class="panel data-panel"><div class="table-toolbar"><h3>Appointment register</h3><span class="muted">Select Review to view customer and technician details</span></div>${table(['Appointment','Customer details','Vehicle / issue','Requested slot','Status','Action'],list.map(a=>[`<strong>${a.id}</strong><small>${dateLabel(a.createdAt?.slice(0,10)||a.date)} requested</small>`,`<strong>${esc(a.customer)}</strong><small>${esc(a.email)} · ${esc(a.phone||'No phone')}</small>`,`<strong>${esc(a.vehicle)}</strong><small>${esc(a.registration)} · ${esc(a.package)}</small>`,`${dateLabel(a.date)}<small>${esc(a.slot)}</small>`,statusPill(a.status),`<button class="btn small primary" data-action="review-appointment" data-id="${a.id}">Review</button>`]))}</section>`}
function customerAppointments(){const list=getAppointments().filter(a=>a.customerId===currentUser.id&&matches(a));setHeading('My Appointments','Book a service and follow the approval status.',actionButton('＋ Book appointment','new-appointment'));$('#pageContent').innerHTML=`<div class="info-banner">Your appointment is first sent to the admin for approval. Once approved, a technician is assigned and a job card becomes visible here after it is created.</div><section class="panel data-panel"><div class="table-toolbar"><h3>Appointment history</h3><span class="muted">${list.length} record(s)</span></div>${table(['Appointment','Vehicle / service','Date & time','Problem description','Status'],list.map(a=>[`<strong>${a.id}</strong>`,`${esc(a.vehicle)}<small>${esc(a.package)} · ${esc(a.registration)}</small>`,`${dateLabel(a.date)}<small>${esc(a.slot)}</small>`,esc(a.problem),statusPill(a.status)]))}</section>`}
function adminVehicles(){const list=getVehicles().filter(matches);setHeading('Vehicle Management','View customer vehicles and current odometer information.',actionButton('＋ Add vehicle','new-vehicle'));$('#pageContent').innerHTML=`<section class="panel data-panel"><div class="table-toolbar"><h3>Registered vehicles</h3><span class="muted">${list.length} vehicle(s)</span></div>${table(['Vehicle','Registration','Owner','Year / fuel','Odometer','Action'],list.map(v=>[`<strong>${esc(v.make)} ${esc(v.model)}</strong><small>${v.id}</small>`,esc(v.registration),esc(v.owner),`${v.year} · ${esc(v.fuel)}`,`${Number(v.km).toLocaleString('en-IN')} km`,`<button class="btn small outline" data-action="edit-vehicle" data-id="${v.id}">Edit</button>`]))}</section>`}
function customerVehicles(){const list=getVehicles().filter(v=>(v.ownerId===currentUser.id||v.owner===currentUser.name)&&matches(v));setHeading('My Vehicles','Your vehicle information and service details.',actionButton('＋ Add vehicle','new-vehicle'));$('#pageContent').innerHTML=`<div class="two-col">${list.map(vehicleCard).join('')||'<section class="panel empty-state">No vehicles found. Add a vehicle to start booking service.</section>'}</div>`}
function adminCustomers(){const list=getUsers().filter(u=>u.role==='customer'&&matches(u));setHeading('Customer Management','Customer accounts and contact details.');$('#pageContent').innerHTML=`<section class="panel data-panel"><div class="table-toolbar"><h3>Customer directory</h3><span class="muted">${list.length} customer(s)</span></div>${table(['Customer','Contact','Vehicles','Appointments','Account'],list.map(u=>[`<strong>${esc(u.name)}</strong><small>${u.id}</small>`,`${esc(u.email)}<small>${esc(u.phone||'Phone not added')}</small>`,getVehicles().filter(v=>v.ownerId===u.id).length,getAppointments().filter(a=>a.customerId===u.id).length,statusPill('Active')]))}</section>`}
function adminTechnicians(){const list=getTechs().filter(matches);setHeading('Technician Management','Review expertise, experience, current availability and assignments.');$('#pageContent').innerHTML=`<div class="three-col">${list.map(t=>`<article class="tech-card"><div class="tech-top"><span class="tech-avatar">${initials(t.name)}</span><div><h3>${esc(t.name)}</h3><p>${esc(t.branch||'Main Branch')}</p></div></div><div class="metric-row"><span>Specialization</span><b>${esc(t.specialization||'General')}</b></div><div class="metric-row"><span>Experience</span><b>${t.experience||0} years</b></div><div class="metric-row"><span>Assigned active jobs</span><b>${getJobs().filter(j=>j.technicianId===t.id&&!['Completed','Delivered'].includes(j.status)).length}</b></div><div class="metric-row"><span>Availability</span>${statusPill(t.status||'Available')}</div><div class="card-actions"><button class="btn secondary small" data-action="view-tech" data-id="${t.id}">View details</button></div></article>`).join('')}</div>`}
function adminJobs(){const list=getJobs().filter(matches);setHeading('Job Card Management','Create, assign and track service work through delivery.',actionButton('＋ Create job card','new-job'));$('#pageContent').innerHTML=`<section class="panel data-panel"><div class="table-toolbar"><h3>All job cards</h3><span class="muted">${list.length} job(s)</span></div>${table(['Job card / vehicle','Customer','Technician','Expected delivery','Estimated cost','Status','Action'],list.map(j=>[`<strong>${j.id}</strong><small>${esc(j.vehicle)} · ${esc(j.registration)}</small>`,esc(j.customer),esc(j.technician||'Unassigned'),dateLabel(j.deliveryDate),money(j.estimatedCost),statusPill(j.status),`<button class="btn small outline" data-action="view-job" data-id="${j.id}">Details</button>`]))}</section>`}
function customerJobs(){const list=getJobs().filter(j=>j.customerId===currentUser.id&&matches(j));setHeading('Job Cards & Service History','See what work was diagnosed, who serviced your vehicle and the expected cost.');$('#pageContent').innerHTML=list.length?`<div class="two-col">${list.map(j=>`<section class="panel">${jobSummary(j)}<div class="subsection-title">Work / diagnosis</div><p>${esc(j.diagnosis||j.complaint||'Diagnosis will be updated by the technician.')}</p><div class="metric-row"><span>Estimated cost</span><b>${money(j.estimatedCost)}</b></div><div class="metric-row"><span>Actual cost</span><b>${money(j.actualCost)}</b></div><div class="metric-row"><span>Expected delivery</span><b>${dateLabel(j.deliveryDate)}</b></div></section>`).join('')}</div>`:'<section class="panel empty-state"><strong>No job cards yet</strong>After admin approves your appointment and creates a job card, it will appear here.</section>'}
function techJobs(){const list=getJobs().filter(j=>(j.technicianId===currentUser.id||j.technician===currentUser.name)&&matches(j));setHeading('My Assigned Jobs','Open a job to update the diagnosis, service work and delivery estimate.');$('#pageContent').innerHTML=`<section class="panel data-panel"><div class="table-toolbar"><h3>Assigned job cards</h3><span class="muted">${list.length} assigned</span></div>${table(['Job card / vehicle','Customer complaint','Customer','Delivery date','Status','Action'],list.map(j=>[`<strong>${j.id}</strong><small>${esc(j.vehicle)} · ${esc(j.registration)}</small>`,esc(j.complaint||'—'),esc(j.customer),dateLabel(j.deliveryDate),statusPill(j.status),`<button class="btn small primary" data-action="update-job" data-id="${j.id}">Update</button>`]))}</section>`}
function invoicesPage(){let list=store.read('payments').filter(p=>(currentUser.role==='admin'||p.customerId===currentUser.id)&&matches(p));setHeading(currentUser.role==='admin'?'Billing & Payments':'Invoices & Payments','Demo invoice and payment records.');if(currentUser.role==='admin')$('#headingActions').innerHTML=actionButton('＋ Create invoice','new-invoice');$('#pageContent').innerHTML=`<section class="panel data-panel"><div class="table-toolbar"><h3>Invoice register</h3><span class="muted">${list.length} invoice(s)</span></div>${table(['Invoice','Customer','Job card','Amount','Due date','Status','Action'],list.map(p=>[`<strong>${p.id}</strong><small>${dateLabel(p.date)}</small>`,esc(p.customer),esc(p.jobId||'—'),money(p.amount),dateLabel(p.dueDate),statusPill(p.status),currentUser.role==='customer'&&p.status!=='Paid'?`<button class="btn small primary" data-action="pay-invoice" data-id="${p.id}">Mark paid (demo)</button>`:'—']))}</section><div class="info-banner">Payments are simulated locally for this frontend project. No real payment gateway is connected.</div>`}
function feedbackPage(){const jobs=getJobs().filter(j=>j.customerId===currentUser.id&&['Completed','Delivered'].includes(j.status));const feedback=store.read('feedback').filter(f=>f.customerId===currentUser.id);setHeading('Customer Feedback','Share your experience after service completion.',actionButton('＋ Give feedback','new-feedback'));$('#pageContent').innerHTML=`<section class="panel">${panelHead('Your feedback','Ratings are stored in this browser')}${feedback.length?table(['Job card','Rating','Comment','Date'],feedback.map(f=>[esc(f.jobId),`${f.rating}/5`,esc(f.comment),dateLabel(f.date)])):'<div class="empty-state">No feedback submitted yet.</div>'}</section><section class="panel">${panelHead('Eligible completed services')}${jobs.length?table(['Job card','Vehicle','Technician','Status','Action'],jobs.map(j=>[j.id,esc(j.vehicle),esc(j.technician),statusPill(j.status),`<button class="btn small secondary" data-action="new-feedback" data-id="${j.id}">Rate service</button>`])):'<div class="empty-state">Feedback becomes available after a job is completed.</div>'}</section>`}
function profilePage(){setHeading('My Profile','View and update your demo account details.');$('#pageContent').innerHTML=`<section class="panel" style="max-width:700px"><div class="vehicle-top"><span class="tech-avatar">${initials(currentUser.name)}</span><div><h3>${esc(currentUser.name)}</h3><p>${roleLabel(currentUser.role)}</p></div></div><form id="profileForm"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required value="${esc(currentUser.name)}"></div><div class="field"><label>Email</label><input value="${esc(currentUser.email)}" disabled></div><div class="field"><label>Phone number</label><input name="phone" value="${esc(currentUser.phone||'')}" placeholder="Enter phone number"></div>${currentUser.role==='technician'?`<div class="field"><label>Specialization</label><input name="specialization" value="${esc(currentUser.specialization||'')}"></div><div class="field"><label>Experience (years)</label><input name="experience" type="number" min="0" value="${currentUser.experience||0}"></div><div class="field"><label>Branch</label><input name="branch" value="${esc(currentUser.branch||'')}"></div>`:''}</div><button class="btn primary" type="submit">Save profile</button></form></section>`;$('#profileForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),users=getUsers(),i=users.findIndex(u=>u.id===currentUser.id);if(i>=0){for(const k of ['name','phone','specialization','branch'])if(fd.has(k))users[i][k]=fd.get(k);if(fd.has('experience'))users[i].experience=Number(fd.get('experience'));store.write('users',users);currentUser=users[i];sessionStorage.setItem('vsc_session',JSON.stringify({id:currentUser.id,name:currentUser.name,email:currentUser.email,role:currentUser.role}));$('#profileName').textContent=currentUser.name;$('#profileAvatar').textContent=initials(currentUser.name);if(currentUser.role==='technician'){const ts=getTechs().map(t=>t.id===currentUser.id?{...t,...currentUser}:t);store.write('technicians',ts)}toast('Profile updated','success');profilePage()}})}
function partsPage(){setHeading('Parts Requests','Request spare parts for an assigned job card.');$('#pageContent').innerHTML=`<section class="panel" style="max-width:760px">${panelHead('New spare parts request','Demo workflow: request is recorded for manager review.')}<form id="partsForm"><div class="form-grid"><div class="field"><label>Job card</label><select name="jobId" required>${getJobs().filter(j=>j.technicianId===currentUser.id).map(j=>`<option value="${j.id}">${j.id} · ${esc(j.vehicle)}</option>`).join('')}</select></div><div class="field"><label>Part name</label><input name="part" required placeholder="e.g. Oil filter"></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="1" value="1" required></div><div class="field"><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></div><div class="field full-field"><label>Reason</label><textarea name="reason" rows="3" required placeholder="Why is this part needed?"></textarea></div></div><button class="btn primary">Submit request</button></form></section><section class="panel">${panelHead('Submitted requests')}<div id="partsList">${renderPartsList()}</div></section>`;$('#partsForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),req=store.read('partsRequests');req.push({id:store.id('PR'),jobId:fd.get('jobId'),part:fd.get('part'),quantity:Number(fd.get('quantity')),priority:fd.get('priority'),reason:fd.get('reason'),technician:currentUser.name,status:'Pending Approval',date:todayDate()});store.write('partsRequests',req);toast('Parts request submitted for approval','success');partsPage()})}
function renderPartsList(){const req=store.read('partsRequests').filter(r=>currentUser.role==='admin'||r.technician===currentUser.name);return req.length?table(['Request','Job card','Part / qty','Technician','Date','Status'],req.map(r=>[`<strong>${r.id}</strong>`,r.jobId,`${esc(r.part)} × ${r.quantity}`,esc(r.technician),dateLabel(r.date),currentUser.role==='admin'&&r.status==='Pending Approval'?`<button class="btn small success" data-action="approve-part" data-id="${r.id}">Approve</button> ${`<button class="btn small danger" data-action="reject-part" data-id="${r.id}">Reject</button>`}`:statusPill(r.status)])):'<div class="empty-state">No parts requests.</div>'}
function reportsPage(){const apps=getAppointments(),jobs=getJobs(),vehicles=getVehicles(),pay=store.read('payments');const counts=['Pending Approval','Confirmed','Rejected','Cancelled'].map(s=>({s,n:apps.filter(a=>a.status===s).length}));setHeading('Reports & Analytics','Summary based on demo records currently stored in this browser.');$('#pageContent').innerHTML=`<div class="stat-grid">${stat('Total Appointments',apps.length,'All request statuses','▣','purple')}${stat('Total Job Cards',jobs.length,'Service records','▤','blue')}${stat('Completed Jobs',jobs.filter(j=>['Completed','Delivered'].includes(j.status)).length,'Delivered or completed','✓','green')}${stat('Revenue Recorded',money(pay.filter(p=>p.status==='Paid').reduce((s,p)=>s+p.amount,0)),'Demo paid invoices','₹','orange')}</div><div class="two-col"><section class="panel">${panelHead('Appointment status report')}${counts.map(c=>`<div class="metric-row"><span>${c.s}</span><b>${c.n}</b></div><div class="progress-track"><span style="width:${apps.length?c.n/apps.length*100:0}%"></span></div>`).join('')}</section><section class="panel">${panelHead('Technician-wise job count')}${getTechs().map(t=>`<div class="metric-row"><span>${esc(t.name)}</span><b>${jobs.filter(j=>j.technicianId===t.id).length} jobs</b></div>`).join('')}</section></div><section class="panel">${panelHead('Vehicle service history')}${table(['Job card','Vehicle','Customer','Technician','Status','Actual cost'],jobs.map(j=>[j.id,`${esc(j.vehicle)}<small>${esc(j.registration)}</small>`,esc(j.customer),esc(j.technician),statusPill(j.status),money(j.actualCost)]))}</section>`}
function modal(title,subtitle,body,submitLabel='Save',onSubmit=null){$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><section class="modal"><header class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal">×</button></header><form id="modalForm"><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn outline" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${submitLabel}</button></footer></form></section></div>`;$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});$('#modalForm').addEventListener('submit',e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(e.currentTarget))})}
function closeModal(){$('#modalRoot').innerHTML=''}
function field(name,label,type='text',value='',required=true,options=null,placeholder=''){let input=options?`<select name="${name}" ${required?'required':''}>${options.map(o=>`<option value="${esc(o.value??o)}" ${String(o.value??o)===String(value)?'selected':''}>${esc(o.label??o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}" rows="3" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}">`;return `<div class="field"><label>${label}</label>${input}</div>`}
function grid(fields){return `<div class="form-grid">${fields.join('')}</div>`}
function newAppointment(){
 const vehicles=getVehicles().filter(v=>currentUser.role==='admin'||v.ownerId===currentUser.id||v.owner===currentUser.name);
 if(currentUser.role==='customer'&&!vehicles.length){toast('Please add a vehicle before booking an appointment.');return newVehicle()}
 const customers=getUsers().filter(u=>u.role==='customer');
 const selected=vehicles[0];const body=grid([
  ...(currentUser.role==='admin'?[field('customerId','Customer','select',customers[0]?.id,true,customers.map(c=>({value:c.id,label:c.name+' · '+c.email})))]:[]),
  field('vehicleId','Vehicle','select',selected?.id,true,vehicles.map(v=>({value:v.id,label:`${v.make} ${v.model} · ${v.registration}`}))),
  field('package','Service package','select','Full Service',true,['General Inspection','Oil Change','Full Service','Brake Service','Engine Diagnostics','AC Repair','Tyre Replacement']),
  field('date','Preferred date','date',futureDate(1)),field('slot','Time slot','select','10:00 AM - 11:00 AM',true,['09:00 AM - 10:00 AM','10:00 AM - 11:00 AM','11:00 AM - 12:00 PM','01:00 PM - 02:00 PM','02:00 PM - 03:00 PM','03:00 PM - 04:00 PM']),
  field('km','Current KM reading','number',selected?.km||0),field('priority','Priority','select','Normal',true,['Normal','High','Urgent']),
  field('problem','Reported problem / customer complaint','textarea','',true,null,'Describe what needs attention.')
 ]);
 modal('Book a service appointment','Choose a vehicle and preferred service slot. Admin approval is required.',body,'Submit appointment',fd=>{
  const v=getVehicles().find(x=>x.id===fd.get('vehicleId'));const customer=currentUser.role==='admin'?customers.find(c=>c.id===fd.get('customerId')):currentUser;
  if(!v||!customer){toast('Please select a valid customer and vehicle.');return}
  if(fd.get('date')<todayDate()){toast('Appointment date cannot be in the past.');return}
  const apps=getAppointments();const clash=apps.some(a=>a.date===fd.get('date')&&a.slot===fd.get('slot')&&a.status!=='Cancelled'&&a.status!=='Rejected');
  if(clash){toast('This time slot already has an appointment in the demo. Choose another slot.');return}
  apps.push({id:store.id('APT'),customerId:customer.id,customer:customer.name,email:customer.email,phone:customer.phone||'',vehicleId:v.id,vehicle:`${v.make} ${v.model}`,registration:v.registration,package:fd.get('package'),date:fd.get('date'),slot:fd.get('slot'),problem:fd.get('problem'),km:Number(fd.get('km')),priority:fd.get('priority'),status:'Pending Approval',createdAt:new Date().toISOString()});store.write('appointments',apps);closeModal();toast('Appointment submitted. Waiting for admin approval.','success');go(currentUser.role==='admin'?'appointments':'appointments');
 });
}
function newVehicle(existing=null){const isEdit=!!existing;const customers=getUsers().filter(u=>u.role==='customer');const v=existing||{};const body=grid([
 ...(currentUser.role==='admin'?[field('ownerId','Vehicle owner','select',v.ownerId||customers[0]?.id,true,customers.map(c=>({value:c.id,label:c.name})))]:[]),
 field('make','Vehicle make', 'text',v.make||''),field('model','Vehicle model','text',v.model||''),field('registration','Registration number','text',v.registration||''),field('year','Manufacturing year','number',v.year||new Date().getFullYear()),field('fuel','Fuel type','select',v.fuel||'Petrol',true,['Petrol','Diesel','Electric','Hybrid','CNG','LPG']),field('km','Current KM reading','number',v.km||0),field('color','Vehicle colour','text',v.color||'',false)
 ]);
 modal(isEdit?'Edit vehicle':'Add vehicle','Enter accurate vehicle details.',body,isEdit?'Update vehicle':'Save vehicle',fd=>{
  const owner=currentUser.role==='admin'?customers.find(c=>c.id===fd.get('ownerId')):currentUser;
  const item={...v,id:v.id||store.id('VSC-V'),ownerId:owner.id,owner:owner.name,make:fd.get('make'),model:fd.get('model'),registration:fd.get('registration'),year:Number(fd.get('year')),fuel:fd.get('fuel'),km:Number(fd.get('km')),color:fd.get('color')};
  const all=getVehicles();if(all.some(x=>x.registration.toLowerCase()===item.registration.toLowerCase()&&x.id!==item.id)){toast('This registration number already exists.');return}
  store.write('vehicles',isEdit?all.map(x=>x.id===item.id?item:x):[...all,item]);closeModal();toast(isEdit?'Vehicle updated':'Vehicle added','success');renderPage();
 });
}
function reviewAppointment(id){const a=getAppointments().find(x=>x.id===id);if(!a)return;const techs=getTechs();const body=`<div class="info-banner">Check the customer's contact details, vehicle issue, requested time and technician availability before confirming.</div><div class="two-col"><section><div class="subsection-title">Customer details</div><div class="metric-row"><span>Name</span><b>${esc(a.customer)}</b></div><div class="metric-row"><span>Email</span><b>${esc(a.email)}</b></div><div class="metric-row"><span>Phone</span><b>${esc(a.phone||'Not provided')}</b></div></section><section><div class="subsection-title">Appointment details</div><div class="metric-row"><span>Vehicle</span><b>${esc(a.vehicle)}</b></div><div class="metric-row"><span>Registration</span><b>${esc(a.registration)}</b></div><div class="metric-row"><span>Requested date</span><b>${dateLabel(a.date)} · ${esc(a.slot)}</b></div><div class="metric-row"><span>Service</span><b>${esc(a.package)}</b></div></section></div><div class="subsection-title">Reported problem</div><p>${esc(a.problem||'No problem description supplied.')}</p><div class="subsection-title">Select technician</div><div class="form-grid">${field('technicianId','Technician','select',techs.find(t=>t.status==='Available')?.id||techs[0]?.id,true,techs.map(t=>({value:t.id,label:`${t.name} · ${t.specialization} · ${t.status}`}))) }${field('estimatedCost','Estimated cost (₹)','number',defaultCost(a.package))}${field('deliveryDate','Expected delivery date','date',futureDate(3))}${field('adminNote','Admin note','textarea','',false,null,'Optional notes for customer / technician')}</div>`;
 modal('Review '+a.id,'Approve the appointment and create a linked job card.',body,'Approve & create job card',fd=>{
  const t=getTechs().find(x=>x.id===fd.get('technicianId'));if(!t){toast('Select a technician.');return}
  const apps=getAppointments();const ix=apps.findIndex(x=>x.id===id);if(ix<0)return;
  if(apps[ix].status==='Confirmed'){toast('This appointment is already confirmed.');return}
  const conflict=getJobs().some(j=>j.technicianId===t.id&&j.startDate===a.date&&!['Completed','Delivered'].includes(j.status));
  if(conflict&&t.status==='Busy'){toast('Technician is currently busy. Please select an available technician.');return}
  apps[ix]={...apps[ix],status:'Confirmed',technicianId:t.id,technician:t.name,adminNote:fd.get('adminNote')};store.write('appointments',apps);
  const jobs=getJobs();if(!jobs.some(j=>j.appointmentId===id)){jobs.push({id:store.id('JC'),appointmentId:id,customerId:a.customerId,customer:a.customer,email:a.email,vehicle:a.vehicle,registration:a.registration,package:a.package,complaint:a.problem,diagnosis:'Awaiting technician inspection',technicianId:t.id,technician:t.name,startDate:a.date,deliveryDate:fd.get('deliveryDate'),estimatedCost:Number(fd.get('estimatedCost')),actualCost:0,status:'Received',tasks:[],updatedAt:new Date().toISOString(),adminNote:fd.get('adminNote')});store.write('jobs',jobs)}
  const techs2=getTechs().map(x=>x.id===t.id?{...x,status:'Busy',availability:'Busy'}:x);store.write('technicians',techs2);const users=getUsers().map(x=>x.id===t.id?{...x,status:'Busy',availability:'Busy'}:x);store.write('users',users);closeModal();toast('Appointment approved. Job card is now visible to the customer and technician.','success');go('appointments');
 });
}
function defaultCost(pkg){return ({'Oil Change':1800,'Full Service':4500,'General Inspection':900,'Brake Service':3200,'Engine Diagnostics':2500,'AC Repair':2800,'Tyre Replacement':3500})[pkg]||2500}
function newJob(){const apps=getAppointments().filter(a=>a.status==='Confirmed');const customers=getUsers().filter(u=>u.role==='customer');const techs=getTechs();const body=grid([
 field('customerId','Customer','select',customers[0]?.id,true,customers.map(c=>({value:c.id,label:c.name}))),
 field('vehicle','Vehicle model','text',''),field('registration','Registration number','text',''),field('package','Service package','select','Full Service',true,['General Inspection','Oil Change','Full Service','Brake Service','Engine Diagnostics','AC Repair','Tyre Replacement']),
 field('technicianId','Assigned technician','select',techs.find(t=>t.status==='Available')?.id,true,techs.map(t=>({value:t.id,label:`${t.name} · ${t.status}`}))),
 field('startDate','Job start date','date',todayDate()),field('deliveryDate','Expected delivery date','date',futureDate(3)),field('estimatedCost','Estimated cost (₹)','number',2500),field('complaint','Customer complaint','textarea','',true,null,'Reported issue'),field('diagnosis','Diagnosis / work details','textarea','',false,null,'Work to be done')
 ]);
 modal('Create job card','Create a service record and share it with the selected customer.',body,'Create job card',fd=>{
  const customer=customers.find(c=>c.id===fd.get('customerId')),tech=techs.find(t=>t.id===fd.get('technicianId'));if(!customer||!tech)return;
  const jobs=getJobs();jobs.push({id:store.id('JC'),customerId:customer.id,customer:customer.name,email:customer.email,vehicle:fd.get('vehicle'),registration:fd.get('registration'),package:fd.get('package'),technicianId:tech.id,technician:tech.name,startDate:fd.get('startDate'),deliveryDate:fd.get('deliveryDate'),estimatedCost:Number(fd.get('estimatedCost')),actualCost:0,complaint:fd.get('complaint'),diagnosis:fd.get('diagnosis'),status:'Received',tasks:[],updatedAt:new Date().toISOString()});store.write('jobs',jobs);closeModal();toast('Job card created and shared with customer','success');go('jobcards');
 });
}
function updateJob(id){const j=getJobs().find(x=>x.id===id);if(!j)return;const canEdit=currentUser.role==='admin'||j.technicianId===currentUser.id;if(!canEdit){toast('You cannot edit this job card.');return}
 const body=grid([field('status','Job status','select',j.status,true,['Received','In Progress','Waiting Parts','Quality Check','Completed','Delivered']),field('deliveryDate','Expected delivery date','date',j.deliveryDate||futureDate(2)),field('estimatedCost','Estimated cost (₹)','number',j.estimatedCost||0),field('actualCost','Actual cost (₹)','number',j.actualCost||0),field('diagnosis','Diagnosis / work performed','textarea',j.diagnosis||'',true,null,'Describe work performed'),field('tasks','Tasks completed (comma separated)','textarea',(j.tasks||[]).join(', '),false,null,'Oil change, brake check, road test')]);
 modal('Update '+j.id,'Changes are immediately reflected in the customer dashboard.',body,'Save job update',fd=>{
  const status=fd.get('status');if(status==='Completed'&&!fd.get('diagnosis').trim()){toast('Add diagnosis/work details before completing the job.');return}
  const jobs=getJobs().map(x=>x.id===id?{...x,status,deliveryDate:fd.get('deliveryDate'),estimatedCost:Number(fd.get('estimatedCost')),actualCost:Number(fd.get('actualCost')),diagnosis:fd.get('diagnosis'),tasks:fd.get('tasks').split(',').map(s=>s.trim()).filter(Boolean),updatedAt:new Date().toISOString()}:x);store.write('jobs',jobs);
  if(['Completed','Delivered'].includes(status)){const t=getTechs().map(t=>t.id===j.technicianId?{...t,status:'Available',availability:'Available'}:t);store.write('technicians',t);const u=getUsers().map(u=>u.id===j.technicianId?{...u,status:'Available',availability:'Available'}:u);store.write('users',u)}
  if(status==='Completed'&&!store.read('payments').some(p=>p.jobId===id)){const p=store.read('payments');p.push({id:store.id('INV'),customerId:j.customerId,customer:j.customer,jobId:id,amount:Number(fd.get('actualCost'))||Number(fd.get('estimatedCost')),date:todayDate(),dueDate:fd.get('deliveryDate'),status:'Pending'});store.write('payments',p)}
  closeModal();toast('Job card updated','success');renderPage();
 });
}
function viewJob(id){const j=getJobs().find(x=>x.id===id);if(!j)return;modal(j.id+' · '+j.vehicle,'Job card details shared with customer.',`<div class="two-col"><div><div class="metric-row"><span>Customer</span><b>${esc(j.customer)}</b></div><div class="metric-row"><span>Vehicle</span><b>${esc(j.vehicle)}</b></div><div class="metric-row"><span>Registration</span><b>${esc(j.registration)}</b></div><div class="metric-row"><span>Service</span><b>${esc(j.package)}</b></div></div><div><div class="metric-row"><span>Technician</span><b>${esc(j.technician)}</b></div><div class="metric-row"><span>Job status</span>${statusPill(j.status)}</div><div class="metric-row"><span>Expected delivery</span><b>${dateLabel(j.deliveryDate)}</b></div><div class="metric-row"><span>Estimated cost</span><b>${money(j.estimatedCost)}</b></div><div class="metric-row"><span>Actual cost</span><b>${money(j.actualCost)}</b></div></div></div><div class="subsection-title">Customer complaint</div><p>${esc(j.complaint||'—')}</p><div class="subsection-title">Diagnosis / work performed</div><p>${esc(j.diagnosis||'Not updated yet')}</p><div class="subsection-title">Tasks</div><p>${esc((j.tasks||[]).join(', ')||'No tasks added yet')}</p>`,'Close',()=>closeModal())}
function viewTech(id){const t=getTechs().find(x=>x.id===id);if(!t)return;const active=getJobs().filter(j=>j.technicianId===id&&!['Completed','Delivered'].includes(j.status));modal(t.name+' · Technician profile','Review technician expertise and current workload.',`<div class="vehicle-top"><span class="tech-avatar">${initials(t.name)}</span><div><h3>${esc(t.name)}</h3><p>${esc(t.email)}</p></div></div><div class="metric-row"><span>Specialization</span><b>${esc(t.specialization)}</b></div><div class="metric-row"><span>Experience</span><b>${t.experience||0} years</b></div><div class="metric-row"><span>Branch</span><b>${esc(t.branch||'Main Branch')}</b></div><div class="metric-row"><span>Phone</span><b>${esc(t.phone||'Not provided')}</b></div><div class="metric-row"><span>Availability</span>${statusPill(t.status||'Available')}</div><div class="metric-row"><span>Active jobs</span><b>${active.length}</b></div><div class="subsection-title">Current assignments</div>${active.length?active.map(j=>`<div class="metric-row"><span>${esc(j.id)} · ${esc(j.vehicle)}</span>${statusPill(j.status)}</div>`).join(''):'<p class="muted">No active job cards assigned.</p>'}`,'Close',()=>closeModal())}
function newInvoice(){const jobs=getJobs().filter(j=>!store.read('payments').some(p=>p.jobId===j.id));const body=grid([field('jobId','Job card','select',jobs[0]?.id,true,jobs.map(j=>({value:j.id,label:`${j.id} · ${j.customer} · ${j.vehicle}`}))),field('amount','Grand total (₹)','number',jobs[0]?.actualCost||jobs[0]?.estimatedCost||0),field('dueDate','Due date','date',futureDate(7)),field('status','Payment status','select','Pending',true,['Pending','Paid'])]);modal('Create invoice','Create a demo invoice for a job card.',body,'Create invoice',fd=>{const j=getJobs().find(x=>x.id===fd.get('jobId'));if(!j){toast('No eligible job card.');return}const p=store.read('payments');p.push({id:store.id('INV'),customerId:j.customerId,customer:j.customer,jobId:j.id,amount:Number(fd.get('amount')),date:todayDate(),dueDate:fd.get('dueDate'),status:fd.get('status')});store.write('payments',p);closeModal();toast('Invoice created','success');go('invoices')})}
function payInvoice(id){const p=store.read('payments').map(x=>x.id===id?{...x,status:'Paid',paidAt:todayDate()}:x);store.write('payments',p);toast('Demo payment marked as paid','success');renderPage()}
function newFeedback(jobId=null){const jobs=getJobs().filter(j=>j.customerId===currentUser.id&&['Completed','Delivered'].includes(j.status));if(!jobs.length){toast('Feedback is available after service completion.');return}const body=grid([field('jobId','Completed job','select',jobId||jobs[0].id,true,jobs.map(j=>({value:j.id,label:`${j.id} · ${j.vehicle}`}))),field('rating','Service rating','select','5',true,['5','4','3','2','1']),field('comment','Comments','textarea','',false,null,'Tell us about your experience')]);modal('Rate your service','Your feedback helps improve service quality.',body,'Submit feedback',fd=>{const all=store.read('feedback');all.push({id:store.id('FB'),jobId:fd.get('jobId'),customerId:currentUser.id,rating:Number(fd.get('rating')),comment:fd.get('comment'),date:todayDate()});store.write('feedback',all);closeModal();toast('Thank you for your feedback','success');go('feedback')})}
function approvePart(id,status){const req=store.read('partsRequests').map(r=>r.id===id?{...r,status,approvedBy:currentUser.name}:r);store.write('partsRequests',req);toast('Parts request '+status.toLowerCase(),'success');renderPage()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='close-modal')return closeModal();if(a==='new-appointment')return newAppointment();if(a==='new-vehicle')return newVehicle();if(a==='edit-vehicle')return newVehicle(getVehicles().find(v=>v.id===id));if(a==='new-job')return newJob();if(a==='review-appointment')return reviewAppointment(id);if(a==='view-tech')return viewTech(id);if(a==='update-job')return updateJob(id);if(a==='view-job')return viewJob(id);if(a==='new-invoice')return newInvoice();if(a==='pay-invoice')return payInvoice(id);if(a==='new-feedback')return newFeedback(id);if(a==='approve-part')return approvePart(id,'Approved');if(a==='reject-part')return approvePart(id,'Rejected');if(a==='go-jobs')return go('jobcards');if(a==='go-appointments')return go('appointments');if(a==='go-vehicles')return go('vehicles');if(a==='go-myjobs')return go('myjobs');if(a==='go-parts')return go('parts');if(a==='go-profile')return go('profile');
});
function toast(msg,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toastRoot').appendChild(el);setTimeout(()=>el.remove(),3300)}
const session=JSON.parse(sessionStorage.getItem('vsc_session')||'null');if(session){currentUser=getUsers().find(u=>u.id===session.id)||session;openApp()}
})();